CREATE TABLE "TIENDA"."PEDIDOS"
   (	"ID" NUMBER(19,0) NOT NULL ENABLE,
	"CLIENTE_ID" NUMBER(10,0) NOT NULL ENABLE,
	"ESTADO" VARCHAR2(20 CHAR) DEFAULT 'nuevo' NOT NULL ENABLE,
