CREATE TABLE tienda.productos (
  id NUMBER(10) PRIMARY KEY,
  sku VARCHAR2(32) NOT NULL UNIQUE,
  nombre VARCHAR2(200) NOT NULL,
  precio NUMBER(12,2),
  descripcion CLOB
);

CREATE TABLE tienda.pedido_lineas (
  pedido_id NUMBER(19) NOT NULL REFERENCES tienda.pedidos (id),
  linea NUMBER(5) NOT NULL,
  producto_id NUMBER(10) NOT NULL,
  cantidad NUMBER(8) NOT NULL,
  CONSTRAINT pedido_lineas_pk PRIMARY KEY (pedido_id, linea)
);

ALTER TABLE tienda.pedido_lineas ADD CONSTRAINT lineas_producto_fk FOREIGN KEY (producto_id) REFERENCES tienda.productos (id);

COMMENT ON TABLE tienda.clientes IS 'Personas que compran en la tienda';
COMMENT ON COLUMN tienda.clientes.email IS 'Correo de acceso';

CREATE OR REPLACE FORCE EDITIONABLE VIEW "TIENDA"."V_VENTAS_CLIENTE" ("CLIENTE_ID", "NOMBRE", "TOTAL") AS
  SELECT c.id, c.nombre, SUM(p.total)
  FROM tienda.clientes c, tienda.pedidos p
  WHERE p.cliente_id = c.id
  GROUP BY c.id, c.nombre;

CREATE MATERIALIZED VIEW tienda.mv_ventas_mes
  BUILD IMMEDIATE REFRESH FORCE ON DEMAND
  AS SELECT TRUNC(creado, 'MM') mes, SUM(total) total FROM tienda.pedidos GROUP BY TRUNC(creado, 'MM');

CREATE OR REPLACE PROCEDURE tienda.recalcula IS
  v NUMBER;
BEGIN
  SELECT COUNT(*) INTO v FROM tienda.pedidos;
  UPDATE tienda.pedidos SET total = total;
END;
/

CREATE INDEX tienda.pedidos_cliente_ix ON tienda.pedidos (cliente_id);
